<?php
$page['dir']='\\housekeeping';$page['housekeeping']=true;$page['rank']=6;require_once __DIR__ . '/../includes/core.php';require_once('./includes/hksession.php');$db=new Database();$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');$where=[];$params=[];foreach(['admin_id'=>'admin_id','action'=>'action_type','target'=>'target_type'] as $q=>$column){if(($_GET[$q]??'')!==''){$where[]="$column = ?";$params[]=$q==='admin_id'?(int)$_GET[$q]:trim($_GET[$q]);}}if(($_GET['from']??'')!==''){$where[]='created_at >= ?';$params[]=strtotime($_GET['from']);}if(($_GET['to']??'')!==''){$where[]='created_at <= ?';$params[]=strtotime($_GET['to'].' +1 day');}$sql='SELECT l.id,l.admin_id,u.username,l.action_type,l.target_type,l.target_id,l.details,l.ip,l.created_at FROM phpretro_admin_action_log l JOIN users u ON u.id=l.admin_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY l.created_at DESC LIMIT 250';$rows=$db->fetchAll($sql,$params);$page['name']='Audit log';$page['category']='tools';require_once('./templates/housekeeping_header.php');
?><div class="page_title"><span class="page_name">Admin audit log</span></div><div class="page_main"><div class="center"><form method="get"><input name="admin_id" placeholder="Admin ID" value="<?php echo $e($_GET['admin_id']??'');?>"><input name="action" placeholder="Action type" value="<?php echo $e($_GET['action']??'');?>"><input name="target" placeholder="Target type" value="<?php echo $e($_GET['target']??'');?>"><input name="from" type="date"><input name="to" type="date"><button>Filter</button></form><table><tr><th>When</th><th>Admin</th><th>Action</th><th>Target</th><th>Details</th><th>IP</th></tr><?php foreach($rows as $r){?><tr><td><?php echo date('c',(int)$r['created_at']);?></td><td><?php echo $e($r['username']);?></td><td><?php echo $e($r['action_type']);?></td><td><?php echo $e($r['target_type']).' #'.(int)$r['target_id'];?></td><td><?php echo $e($r['details']);?></td><td><?php echo $e($r['ip']);?></td></tr><?php }?></table></div></div><?php require_once('./templates/housekeeping_footer.php');?>